select s.id as sessionId, i.id as itemId, s.status as status from cf_class_review_item i inner join cf_class_review_session s on s.id = i.session_id and s.del_flag = '0' where i.student_id = #{studentId} and date_format(s.class_time, '%Y%m%d') = date_format(now(), '%Y%m%d')
and s.teacher_user_id = #{teacherUserId}
order by s.class_time desc, i.id desc limit 1



    s.del_flag = '0'
    and s.teacher_user_id = #{teacherUserId}
    and s.subject = #{subject}
    and s.status = #{status}

        and date_format(s.class_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')


        and date_format(s.class_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')


order by s.class_time desc, s.id desc

